function refoldGrid(grid: number[][], rows: number, cols: number): number[][] {
  const flat = grid.flat();
  if (rows * cols !== flat.length) return grid;
  const out: number[][] = [];
  for (let r = 0; r < rows; r++) out.push(flat.slice(r * cols, (r + 1) * cols));
  return out;
}

