function refoldGrid(grid: number[][], rows: number, cols: number): number[][] {
  const m = grid.length, n = grid[0].length;
  if (rows * cols !== m * n) return grid;
  const out: number[][] = Array.from({ length: rows }, () => new Array(cols));
  for (let k = 0; k < m * n; k++) {
    out[Math.floor(k / cols)][k % cols] = grid[Math.floor(k / n)][k % n];
  }
  return out;
}

